const input = $input.first().json;
const gate  = $('Policy Gate - Validate Constraints').first().json;

const CONFIG = {
  blockSeverities: ['BLOCKER', 'CRITICAL'],
  autoFixSeverities: ['CRITICAL', 'MAJOR'],
  autoFixTypes: ['BUG', 'VULNERABILITY', 'CODE_SMELL'],
  excludeAutoFixSeverities: ['BLOCKER'],
  maxMajorIssues: 15,
  maxTrivyHigh: 3,
  maxOwaspItems: 5,
  maxZapMedium: 2,
  largeFileLineThreshold: 400,
  maxTokens: 8192,
  model: 'claude-haiku-4-5-20251001',
};

let fileContent = '';
let fileSha     = '';
let filePath    = '';

try {
  const raw = input.content;
  if (typeof raw === 'string') {
    fileContent = Buffer.from(raw.replace(/\n/g, ''), 'base64').toString('utf-8');
  } else if (Array.isArray(raw)) {
    fileContent = Buffer.from(raw.join('').replace(/\n/g, ''), 'base64').toString('utf-8');
  }
  fileSha  = input.sha  || '';
  filePath = input.path || '';
} catch (e) {
  throw new Error(`Decodage GitHub impossible : ${e.message}`);
}

if (!fileContent || fileContent.length < 10) {
  const preview = JSON.stringify(input.content ?? null).substring(0, 200);
  throw new Error(`Fichier vide ou non decode. Contenu brut : ${preview}`);
}

const fileName = filePath || gate.target_file_path;
if (!fileName) {
  throw new Error(
    'Aucun fichier cible determine. Verifier que Policy Gate fournit ' +
    'target_file_path ou que le noeud GitHub renvoie bien "path".'
  );
}

const shortName    = fileName.split('/').pop();
const lineCount    = fileContent.split('\n').length;
const isLargeFile  = lineCount > CONFIG.largeFileLineThreshold;

const ext = (shortName.split('.').pop() || '').toLowerCase();
const LANG_MAP = {
  java: { name: 'Java/Spring',  dependencyFile: 'pom.xml ou build.gradle', loggerPattern: 'SLF4J / Log4j / java.util.logging' },
  kt:   { name: 'Kotlin',       dependencyFile: 'build.gradle', loggerPattern: 'SLF4J / Log4j' },
  ts:   { name: 'TypeScript',   dependencyFile: 'package.json', loggerPattern: 'console / winston / pino' },
  js:   { name: 'JavaScript',   dependencyFile: 'package.json', loggerPattern: 'console / winston / pino' },
  py:   { name: 'Python',       dependencyFile: 'requirements.txt', loggerPattern: 'logging / loguru / structlog' },
  cs:   { name: 'C#/.NET',      dependencyFile: '.csproj', loggerPattern: 'ILogger / Serilog / NLog' },
  go:   { name: 'Go',           dependencyFile: 'go.mod', loggerPattern: 'log / slog / zap' },
  php:  { name: 'PHP',          dependencyFile: 'composer.json', loggerPattern: 'monolog / error_log' },
  rb:   { name: 'Ruby',         dependencyFile: 'Gemfile', loggerPattern: 'Rails.logger / Logger' },
};
const lang = LANG_MAP[ext] || { name: 'code source', dependencyFile: 'fichier de dependances', loggerPattern: 'framework logger' };

const enriched = gate.enrichedData || {};
const ai       = gate.aiAnalysis   || {};

const sonarIssues = enriched.sonar?.issues || [];
const fileIssues  = sonarIssues.filter(i => {
  const comp = i.component || '';
  return comp.includes(fileName) || comp.endsWith(`/${shortName}`) || comp.endsWith(`:${shortName}`);
});

const agentFixableIssues = fileIssues.filter(i => {
  const sevOK   = CONFIG.autoFixSeverities.includes(i.severity);
  const typeOK  = CONFIG.autoFixTypes.includes(i.type);
  const notBlocker = !CONFIG.excludeAutoFixSeverities.includes(i.severity);
  return sevOK && typeOK && notBlocker;
});

const excludedBlockers = fileIssues.filter(i => CONFIG.excludeAutoFixSeverities.includes(i.severity));

const formatSonar = (b, idx) =>
  `  SONAR-${idx}: [${b.severity}/${b.type}] ${b.rule ? b.rule + ' — ' : ''}${b.message} (ligne ${b.line ?? '?'})`;

const sonarList = agentFixableIssues.map((b, i) => formatSonar(b, i + 1));

const pickSeverity = (c) => (c.severity || c.Severity || '').toUpperCase();
const trivyCves    = enriched.trivy?.cves || [];
const trivyCrit    = trivyCves.filter(c => pickSeverity(c) === 'CRITICAL');
const trivyHigh    = trivyCves.filter(c => pickSeverity(c) === 'HIGH').slice(0, CONFIG.maxTrivyHigh);

const cveId  = (c) => c.VulnerabilityID || c.id || c.cve || 'CVE-inconnue';
const cvePkg = (c) => c.PkgName || c.pkg || c.package || 'paquet inconnu';

const trivyList = [
  ...trivyCrit.map((c, i) =>
    `  TRIVY-${i + 1}: [CRITICAL] ${cveId(c)} dans ${cvePkg(c)} — ${(c.Title || c.description || '').substring(0, 80)}`),
  ...trivyHigh.map((c, i) =>
    `  TRIVY-${trivyCrit.length + i + 1}: [HIGH] ${cveId(c)} dans ${cvePkg(c)}`),
];

const owaspCritical = enriched.owasp?.critical || 0;
const owaspHigh     = enriched.owasp?.high     || 0;
const owaspCves     = (enriched.owasp?.cves || []).slice(0, CONFIG.maxOwaspItems);
const owaspList     = owaspCves.map((c, i) =>
  `  OWASP-${i + 1}: [${c.severity || 'HIGH'}] ${c.name || c.id || 'CVE'} dans ${c.fileName || c.pkg || 'dependance'}`
);

const zapAlerts = enriched.zap?.alerts || [];
const riskOf    = (a) => Number(a.riskcode ?? a.risk ?? 0);
const zapHigh   = zapAlerts.filter(a => riskOf(a) >= 3);
const zapMedium = zapAlerts.filter(a => riskOf(a) === 2).slice(0, CONFIG.maxZapMedium);

const zapList = [
  ...zapHigh.map((a, i) =>
    `  ZAP-${i + 1}: [HIGH] ${a.name || a.alert || 'Alerte'} — ${(a.description || a.desc || '').substring(0, 60)}`),
  ...zapMedium.map((a, i) =>
    `  ZAP-${zapHigh.length + i + 1}: [MEDIUM] ${a.name || a.alert || 'Alerte'}`),
];

const totalSonar = sonarList.length;
const totalTrivy = trivyList.length;
const totalOwasp = owaspList.length;
const totalZap   = zapList.length;
const totalAll   = totalSonar + totalTrivy + totalOwasp + totalZap;

if (totalAll === 0) {
  return [{
    json: {
      skipAutoFix: true,
      reason: `Aucun finding auto-corrigeable pour ${shortName}. ` +
              `${excludedBlockers.length} BLOCKER(s) exclu(s) par securite. ` +
              `${fileIssues.length - excludedBlockers.length} autre(s) non eligible(s).`,
      decision: gate.decision || 'UNKNOWN',
      fileName: fileName,
      excludedBlockers: excludedBlockers.length,
      findingsTotal: fileIssues.length,
    }
  }];
}

const sections = [];

if (totalSonar > 0) {
  sections.push(`SONARQUBE — ${totalSonar} finding(s) auto-corrigeable(s) dans ${shortName} :\n${sonarList.join('\n')}`);
}
if (totalTrivy > 0) {
  sections.push(
    `TRIVY (image/conteneur) — ${totalTrivy} CVE :\n${trivyList.join('\n')}\n` +
    `  Note : ces CVE se corrigent dans le Dockerfile ou ${lang.dependencyFile}, pas dans ce fichier. Ajouter des commentaires TODO.`
  );
}
if (totalOwasp > 0) {
  sections.push(
    `OWASP DEPENDENCY-CHECK — ${totalOwasp} vulnerabilite(s) :\n${owaspList.join('\n')}\n` +
    `  Note : mise a jour de ${lang.dependencyFile} necessaire. Ajouter des commentaires TODO.`
  );
} else if (owaspCritical > 0 || owaspHigh > 0) {
  sections.push(
    `OWASP DEPENDENCY-CHECK — ${owaspCritical} critique(s), ${owaspHigh} haute(s), sans detail disponible.`
  );
}
if (totalZap > 0) {
  sections.push(
    `ZAP (DAST) — ${zapHigh.length} haute(s), ${zapMedium.length} moyenne(s) :\n${zapList.join('\n')}\n` +
    `  Note : peut necessiter validation d'entree, protection CSRF ou en-tetes de securite.`
  );
}

if (excludedBlockers.length > 0) {
  sections.push(
    `BLOCKER EXCLU(S) DE L'AUTO-FIX (${excludedBlockers.length}) :\n` +
    excludedBlockers.map((b, i) => `  EXCLU-${i+1}: [${b.severity}/${b.type}] ${b.rule || ''} — ${b.message} (ligne ${b.line ?? '?'})`).join('\n') +
    `\n  Ces findings necessitent une revue humaine obligatoire. Ne pas corriger automatiquement.`
  );
}

if (ai.developerActions) sections.push(`ACTIONS DEVELOPPEUR :\n${ai.developerActions}`);
if (ai.securityIssues)   sections.push(`PROBLEMES DE SECURITE IDENTIFIES :\n${ai.securityIssues}`);

// ── Guide de correction de l'agent Developer Guidance (WF1) ──
const wfDevGuide  = gate.developerGuide || gate.aiAnalysis?.developerGuide || {};
const guideIssues = Array.isArray(wfDevGuide.issues) ? wfDevGuide.issues : [];
const guideForFile = guideIssues.filter(i =>
  String(i.source || '').toUpperCase() === 'SONARQUBE' &&
  ((i.file || '').endsWith(shortName) || (i.file || '').includes(fileName))
);
if (guideForFile.length > 0) {
  sections.push(
    `GUIDE DE CORRECTION DETAILLE (agent Developer Guidance) — suis PRECISEMENT ces demarches pour chaque finding correspondant :\n` +
    guideForFile.map(g =>
      `  [${g.rule || g.id}] ligne ${g.line ?? '?'} — ${g.title || ''}\n` +
      `    Probleme : ${g.problem || ''}\n` +
      `    Etapes : ${(g.howToFix || []).join(' | ')}\n` +
      (g.codeExample && g.codeExample.after ? `    Exemple corrige : ${String(g.codeExample.after).substring(0, 250)}\n` : '') +
      `    Verification : ${g.verification || ''}`
    ).join('\n')
  );
}

const fixContext = sections.join('\n\n');

const incidentId = gate.incidentId || gate.incidentUUID || 'unknown';
const fileSlug   = shortName.replace(/\.[^.]+$/, '').replace(/[^a-zA-Z0-9]/g, '-').toLowerCase();

const decision = (gate.decision || 'UNKNOWN').toUpperCase();
const buildNum = gate.buildNumber || gate.build_number || 'unknown';
const branchPrefix = decision === 'BLOCK' ? 'fix/ai-blocked' : 'fix/ai';
const branchName   = `${branchPrefix}-${fileSlug}-${Date.now()}`;

const commitMsg = decision === 'BLOCK'
  ? `fix(security): auto-remediation for BLOCKED build #${buildNum} — ${totalAll} finding(s) in ${shortName}`
  : `fix(security): automated fix for ${totalAll} finding(s) in ${shortName}`;

const systemPrompt = `Tu es un ingenieur DevSecOps expert. Tu analyses les resultats de quatre scanners de securite : SonarQube (SAST), Trivy (image), OWASP Dependency-Check (dependances) et OWASP ZAP (DAST).

Tu produis UNIQUEMENT du JSON valide : pas de markdown, pas de backticks, aucune explication hors du JSON.
Le champ patchedCode doit contenir le fichier COMPLET, avec tous les problemes corrigeables traites.
Echappe correctement les caracteres speciaux JSON (retours ligne \\n, guillemets \", antislashs \\\\).

REGLES DE SECURITE ABSOLUES :
- Corrige TOUS les findings SonarQube listes pour ce fichier, en une seule passe.
- Pour les CVE Trivy/OWASP : ajoute des commentaires TODO, ne modifie pas les versions ici.
- Pour les alertes ZAP : applique les corrections possibles au niveau du code.
- N'importe JAMAIS une classe ou un module qui n'existe pas deja dans le projet.
- Ne reference JAMAIS un nouveau fichier (DTO, util, helper) absent du depot.
- Si une correction exige de creer une nouvelle classe, mets un TODO a la place.
- Ne supprime JAMAIS une methode, un champ ou une logique existante, sauf si explicitement identifie comme un bug.
- Ne modifie JAMAIS une signature publique dont d'autres fichiers dependent.
- Conserve tous les imports utilises.
- Le fichier produit DOIT compiler sans erreur.
- Preserve le style, l'indentation et la langue des commentaires du fichier d'origine.`;

const largeFileWarning = isLargeFile
  ? `\nATTENTION : fichier volumineux (${lineCount} lignes). Si le fichier complet ne tient pas dans ta reponse, corrige en priorite les findings CRITICAL et signale-le dans patchDescription.\n`
  : '';

const blockContext = decision === 'BLOCK'
  ? `\nCONTEXTE : Ce build est actuellement BLOQUE pour raison de securite (CVE critique ou BLOCKER detecte). ` +
    `Cette correction est une remédiation partielle qui sera livree APRES resolution manuelle des bloqueurs. ` +
    `Ne corrige PAS les BLOCKER listes dans la section "BLOCKER EXCLU(S)" — ils necessitent une revue humaine.\n`
  : '';

const userPrompt = `Corrige les problemes de securite dans ce fichier ${lang.name}.

Fichier : ${fileName} (${lineCount} lignes)
Statut du build : ${decision}
Findings auto-corrigeables : ${totalAll} au total — SonarQube ${totalSonar}, Trivy ${totalTrivy}, OWASP ${totalOwasp}, ZAP ${totalZap}
${blockContext}${largeFileWarning}
=== CONTENU ACTUEL DU FICHIER ===
${fileContent}
=== FIN DU CONTENU ===

${fixContext}

MOTIFS DE CORRECTION (applique le motif correspondant a chaque finding) :
- Secret ou mot de passe en dur -> externaliser via variable d'environnement ou configuration
- Requete construite par concatenation -> requete parametree
- Algorithme cryptographique faible -> equivalent moderne et sur
- Ressource non fermee -> gestion automatique de fermeture (try-with-resources ou equivalent)
- Dereferencement potentiellement nul -> verification explicite avant usage
- Comparaison d'objets avec == -> methode d'egalite appropriee du langage
- Bloc catch vide -> journaliser ou propager l'exception
- Sortie console directe -> logger du framework en place (${lang.loggerPattern})
- Exception generique -> exception specifique ou personnalisee
- Litteral duplique -> constante privee statique
- Complexite cognitive elevee -> extraction en methodes privees plus courtes
- Methode vide -> commentaire explicatif ou exception explicite
- Variable inutilisee -> suppression
- Conditions imbriquees inutilement -> fusion des conditions
- Injection de commande ou path traversal -> validation stricte de l'entree
- CVE de dependance ou d'image -> commentaire TODO uniquement

Reponds UNIQUEMENT avec ce JSON :
{"incidentId":"${incidentId}","patchDescription":"resume des corrections appliquees","filePath":"${fileName}","patchedCode":"FICHIER_COMPLET_CORRIGE","commitMessage":"${commitMsg}","branchName":"${branchName}"}`;

const body = {
  model: CONFIG.model,
  max_tokens: CONFIG.maxTokens,
  temperature: 0,
  system: systemPrompt,
  messages: [{ role: 'user', content: userPrompt }],
};

return [{
  json: {
    claudeBodyString: JSON.stringify(body),
    file_sha:         fileSha,
    file_path:        fileName,
    repository_owner: gate.repository_owner || '',
    repository_name:  gate.repository_name  || '',
    default_branch:   gate.default_branch   || 'main',
    incidentId:       incidentId,
    projectId:        gate.projectId || '',
    branchName:       branchName,
    commitMessage:    commitMsg,
    decision:         decision,
    buildNumber:      buildNum,
    skipAutoFix:      false,
    excludedBlockers: excludedBlockers.length,
    excludedBlockerRules: excludedBlockers.map(b => b.rule || b.ruleKey || 'UNKNOWN'),
    language:         lang.name,
    findingsTotal:    totalAll,
    findingsBySource: {
      sonar: totalSonar,
      trivy: totalTrivy,
      owasp: totalOwasp,
      zap:   totalZap,
    },
    fileLineCount:    lineCount,
    largeFileWarning: isLargeFile,
  }
}];

const response = $input.first().json;
const prepareNode = $('Prepare - Code Patch Body').first().json;

// ── 1. Extraire le texte de la réponse Claude ──
const content = response.content?.[0]?.text
  || response.content?.text
  || (typeof response.content === 'string' ? response.content : null);

if (!content) {
  throw new Error('Claude: réponse vide. Réponse brute: ' + JSON.stringify(response).substring(0, 300));
}

// ── 2. Parser le JSON (3 stratégies de fallback) ──
let parsed = null;
let cleaned = content.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

// Stratégie 1 : JSON.parse direct
try {
  parsed = JSON.parse(cleaned);
} catch (e1) {
  // Stratégie 2 : extraire le premier { ... } complet
  const first = cleaned.indexOf('{');
  const last  = cleaned.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try {
      parsed = JSON.parse(cleaned.substring(first, last + 1));
    } catch (e2) {
      // Stratégie 3 : tenter de réparer les erreurs courantes
      try {
        let repaired = cleaned.substring(first, last + 1)
          .replace(/,\s*}/g, '}')      // trailing comma
          .replace(/,\s*]/g, ']');     // trailing comma in arrays
        parsed = JSON.parse(repaired);
      } catch (e3) {
        parsed = null;
      }
    }
  }
}

// ── 3. Valider que patchedCode existe et n'est pas vide ──
if (!parsed) {
  throw new Error(
    'PARSE FAILED: impossible de parser le JSON de Claude. ' +
    'Réponse (500 premiers car.): ' + content.substring(0, 500)
  );
}

if (!parsed.patchedCode || parsed.patchedCode.trim().length < 20) {
  throw new Error(
    'PATCH ABORTED: patchedCode vide ou trop court (' +
    (parsed.patchedCode?.length || 0) + ' car.). ' +
    'Refus d\'écraser le fichier. ' +
    'Description: ' + (parsed.patchDescription || 'aucune')
  );
}

// ── 4. Construire l'output avec fallbacks robustes ──
const branchName = (parsed.branchName && parsed.branchName.length > 5)
  ? parsed.branchName
  : prepareNode.branchName || `fix/ai-patch-${Date.now()}`;

const incidentId = parsed.incidentId && parsed.incidentId !== 'unknown'
  ? parsed.incidentId
  : prepareNode.incidentId || 'unknown';

const filePath = parsed.filePath
  || prepareNode.file_path
  || (() => { throw new Error('Aucun filePath determine — verifier le Policy Gate'); })();

const commitMessage = parsed.commitMessage
  || prepareNode.commitMessage
  || 'fix: automated DevSecOps AI security patch';

return [{
  json: {
    incidentId,
    patchDescription: parsed.patchDescription || '',
    filePath,
    patchedCode:      parsed.patchedCode,
    commitMessage,
    branchName,
    file_sha:         prepareNode.file_sha || '',
    file_path:        filePath,
    repository_owner: prepareNode.repository_owner
      || $('Policy Gate - Validate Constraints').first().json.repository_owner || '',
    repository_name:  prepareNode.repository_name
      || $('Policy Gate - Validate Constraints').first().json.repository_name || '',
    default_branch:   prepareNode.default_branch || 'main',
  }
}];

// Le backend envoie l'incident complet dans body
const body = $input.first().json.body || $input.first().json;
const incident = body.incident || body;

// aiAnalysis est stocké comme string JSON → on le parse
const aiAnalysis = typeof incident.aiAnalysis === 'string'
  ? JSON.parse(incident.aiAnalysis)
  : (incident.aiAnalysis || {});

const enriched = incident.metadata?.enrichedData || {};
const githubRepo = incident.project?.githubRepo;
if (!githubRepo) { throw new Error('githubRepo non disponible dans le projet'); }

// ── Ciblage dynamique : trouver le fichier avec le plus de BLOCKER/CRITICAL ──
const targetFile = (() => {
  const issues = enriched.sonar?.issues || [];
  const critical = issues.filter(i => ['BLOCKER','CRITICAL'].includes(i.severity));
  if (critical.length === 0) { throw new Error('Aucun fichier avec findings BLOCKER/CRITICAL trouvé dans SonarQube'); }
  const fileCounts = {};
  critical.forEach(i => {
    const f = (i.component || '').replace('pfe-app-test:', '');
    if (f) fileCounts[f] = (fileCounts[f] || 0) + 1;
  });
  const sorted = Object.entries(fileCounts).sort((a, b) => b[1] - a[1]);
  return sorted[0][0];
})();

// Reconstruire le format incidentData attendu par le Policy Gate
const incidentData = {
  incidentId:       incident.id,
  projectId:        incident.projectId,
  githubRepo:       githubRepo,
  githubToken:      incident.project?.githubToken || null,
  branch:           'main',
  decision:         aiAnalysis.decision || 'FIX_PROPOSED',
  confidenceScore:  (aiAnalysis.confidenceScore || 90) / 100,
  riskLevel:        (aiAnalysis.securityLevel || 'high').toLowerCase(),
  aiAnalysis:       aiAnalysis,
  jenkinsJobName:   incident.jenkinsJobName,
  buildNumber:      incident.buildNumber,
  enrichedData:     enriched,
  repository_owner: githubRepo.split('/')[0],
  repository_name:  githubRepo.split('/')[1],
  target_file_path: targetFile,
  default_branch:   'main',
};

return [{ json: { incidentData } }];

